  {
    "id": "about_story_01",
    "elType": "section",
    "settings": {
      "layout": "boxed",
      "padding": {"top": "100", "bottom": "100", "left": "20", "right": "20", "unit": "px"},
      "background_background": "classic",
      "background_color": "#FFFFFF",
      "structure": "20"
    },
    "elements": [
      {
        "id": "about_story_col1",
        "elType": "column",
        "settings": {"_column_size": 50, "content_position": "center", "padding": {"right": "40", "unit": "px"}},
        "elements": [
          {
            "id": "about_story_img",
            "elType": "widget",
            "widgetType": "image",
            "settings": {
              "image": {"url": "/wp-content/uploads/about-story.jpg", "id": ""},
              "image_size": "full",
              "width": {"size": 100, "unit": "%"},
              "border_radius": {"top": "16", "right": "16", "bottom": "16", "left": "16", "unit": "px"}
            }
          }
        ]
      },
      {
        "id": "about_story_col2",
        "elType": "column",
        "settings": {"_column_size": 50, "content_position": "center", "padding": {"left": "40", "unit": "px"}},
        "elements": [
          {
            "id": "about_story_label",
            "elType": "widget",
            "widgetType": "text-editor",
            "settings": {
              "editor": "<p style='color:#13A89E;font-weight:700;font-size:14px;text-transform:uppercase;letter-spacing:2px;'>Our Story</p>"
            }
          },
          {
            "id": "about_story_title",
            "elType": "widget",
            "widgetType": "heading",
            "settings": {
              "title": "Committed to Your Health Since 2008",
              "header_size": "h2",
              "title_color": "#0B2545",
              "typography_typography": "custom",
              "typography_font_family": "Plus Jakarta Sans",
              "typography_font_size": {"size": 36, "unit": "px"},
              "typography_font_weight": "800",
              "typography_line_height": {"size": 1.3, "unit": "em"}
            }
          },
          {
            "id": "about_story_text",
            "elType": "widget",
            "widgetType": "text-editor",
            "settings": {
              "editor": "<p>Founded with a passion for holistic healthcare, Chirox Clinic has been at the forefront of chiropractic and physiotherapy care for over 15 years. Our journey began with a simple mission: to help people live pain-free, active lives without relying on medication or invasive procedures.</p><p>Today, we are proud to have helped thousands of patients recover from injuries, manage chronic conditions, and improve their overall quality of life through evidence-based treatments and personalized care plans.</p>",
              "text_color": "#555555",
              "typography_typography": "custom",
              "typography_font_size": {"size": 16, "unit": "px"},
              "typography_line_height": {"size": 1.8, "unit": "em"}
            }
          }
        ]
      }
    ]
  },
